<script setup lang="ts">import { useQuery } from '@tanstack/vue-query';import { adminApi } from '../api';import DsBadge from '@/shared/ui/DsBadge.vue';import DsCard from '@/shared/ui/DsCard.vue';import DsPageHeader from '@/shared/ui/DsPageHeader.vue';import DsState from '@/shared/ui/DsState.vue';const q=useQuery({queryKey:['admin','menus'],queryFn:adminApi.menus})</script><template><section><DsPageHeader eyebrow="NAVIGATION" title="Menu Management" description="Configure application navigation metadata and permission visibility."/><DsCard class="panel"><DsState v-if="q.isPending.value" kind="loading"/><DsState v-else-if="q.isError.value" kind="error" title="Unable to load menus"/><DsState v-else-if="!q.data.value?.length" kind="empty" title="No menus configured"/><table v-else><thead><tr><th>Menu</th><th>Code</th><th>Route</th><th>Permission</th><th>Status</th></tr></thead><tbody><tr v-for="m in q.data.value" :key="m.PublicID"><td><strong>{{m.Name}}</strong></td><td><code>{{m.Code}}</code></td><td>{{m.Route?.Valid?m.Route.String:'—'}}</td><td>{{m.PermissionCode?.Valid?m.PermissionCode.String:'—'}}</td><td><DsBadge :tone="m.Active?'success':'neutral'">{{m.Active?'Active':'Inactive'}}</DsBadge></td></tr></tbody></table></DsCard></section></template><style scoped>section{padding:32px}.panel{padding:0;overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:15px 18px;border-bottom:1px solid var(--ds-border);font-size:14px}th{color:var(--ds-text-muted);font-size:12px;text-transform:uppercase;letter-spacing:.05em}tbody tr:last-child td{border-bottom:0}code{color:var(--ds-text-secondary)}@media(max-width:640px){section{padding:20px}}</style>